def toPostfix(expr):
    prec = {'+': 1, '-': 1, '*': 2, '/': 2, '^': 3}
    out = []
    ops = []
    for c in expr:
        if c.isdigit():
            out.append(c)
        elif c == '(':
            ops.append(c)
        elif c == ')':
            while ops[-1] != '(':
                out.append(ops.pop())
            ops.pop()
        else:
            while ops and ops[-1] != '(' and (
                    prec[ops[-1]] > prec[c] or (prec[ops[-1]] == prec[c] and c != '^')):
                out.append(ops.pop())
            ops.append(c)
    while ops:
        out.append(ops.pop())
    return "".join(out)
